SELECT NULL, v.titulo, 'padrao', 'E0', v.ficha->>'mecanismo', 'imagem', 'meta', v.tags, v.ficha || jsonb_build_object('fonte', 'Padrão da agência Aceleriq (Mesa Ads v2, 24/09/2026), derivado de docs/mesa-ads/pesquisa (DOSSIE-CRIATIVOS.md e PESQUISA-V2.md) e de _shared/conhecimento-ads.ts. Sem marca de terceiros e sem veiculação.', 'o_que_substituir', 'Foto, textos, números, preço, prazo e provas pelos reais do cliente. O gancho verbal é exemplo: reescrever com a linguagem do público. O que está entre colchetes só entra confirmado pela equipe.'), false, true
